      if (raw <= 4)  return { label: _sajuQuantumText("sq_8944_prop_label"),   tier: 'near',   raw: raw };
      if (raw <= 10) return { label: _sajuQuantumText("sq_8945_prop_label"), tier: 'middle', raw: raw };
