      add(ctx.tenGodsDistribution.재성 >= 1 && ctx.tenGodsDistribution.관성 >= 1, '재관 혼재 흐름', 12);
      add(ctx.harmfulTenGodGroups.indexOf('재성') >= 0 || ctx.harmfulTenGodGroups.indexOf('관성') >= 0, '재성·관성 중 하나가 기신으로 작동', 10);
