    earth: { color: '#8A6212', soft: 'rgba(138,98,18,.11)', border: 'rgba(138,98,18,.32)' },  // 황 5.28:1
    metal: { color: '#4A5A68', soft: 'rgba(74,90,104,.10)', border: 'rgba(74,90,104,.32)' },  // 백 6.86:1
